function band(x, c, y, col, trim) { const pts = [c.left, c.bottom, c.right]; for (let i = 0; i < 2; i++) { const a = up(pts[i], y), b = up(pts[i + 1], y); line(x, a, b, col, 3.2); const len = Math.hypot(b[0] - a[0], b[1] - a[1]); for (let d = 1.5; d < len; d += 3.2) { const u = d / len; const px = a[0] + (b[0] - a[0]) * u, py = a[1] + (b[1] - a[1]) * u; x.fillStyle = trim; path(x, [[px, py - 1.4], [px + 1.2, py], [px, py + 1.4], [px - 1.2, py]]); x.fill(); } } }
function azulejo(x, c, ht) { const pts = [c.left, c.bottom, c.right]; for (let i = 0; i < 2; i++) { const a = up(pts[i], 2), b = up(pts[i + 1], 2); const len = Math.hypot(b[0] - a[0], b[1] - a[1]); for (let d = 0; d < len; d += 2.6) { const u = d / len; const px = a[0] + (b[0] - a[0]) * u, py = a[1] + (b[1] - a[1]) * u; x.fillStyle = Math.floor(d / 2.6) % 2 ? '#2a5ea7' : '#efe6d4'; x.fillRect(px, py - ht, 2.4, ht); } } }
function buttress(x, p, q, t, ht, s) { const a = lerp(p, q, t); const dx = (q[0] - p[0]) / Math.hypot(q[0] - p[0], q[1] - p[1]) * 3, dy = (q[1] - p[1]) / Math.hypot(q[0] - p[0], q[1] - p[1]) * 3; const nx = dy * 1.4, ny = -dx * 1.4; const sgn = p[1] > q[1] ? -1 : 1; const pts = [[a[0], a[1]], [a[0] + dx, a[1] + dy], [a[0] + dx - nx * sgn, a[1] + dy - ny * sgn + 0], [a[0] - nx * sgn, a[1] - ny * sgn]]; const dz = ht * 0.7; face(x, [up(pts[0], dz), up(pts[1], dz), pts[1], pts[0]], s.wall, {k: -0.2, seed: 31, amp: 0.1}); face(x, [up(pts[3], dz), up(pts[0], dz), pts[0], pts[3]], s.wall, {k: sgn > 0 ? -0.34 : -0.05, seed: 32, amp: 0.1}); x.fillStyle = shade(s.wall, 0.08); path(x, [up(pts[0], dz), up(pts[1], dz), up(pts[2], dz + 3), up(pts[3], dz + 3)]); x.fill(); outline(x, [up(pts[0], dz), up(pts[1], dz), up(pts[2], dz + 3), up(pts[3], dz + 3)], 0.5); }
