function barrel(x, px, py) { const g = x.createLinearGradient(px - 4, 0, px + 4, 0); g.addColorStop(0, '#4e341d'); g.addColorStop(0.45, '#9a6f42'); g.addColorStop(1, '#3d2814'); x.fillStyle = g; x.beginPath(); x.moveTo(px - 4, py - 2); x.quadraticCurveTo(px - 5, py - 6, px - 4, py - 10); x.lineTo(px + 4, py - 10); x.quadraticCurveTo(px + 5, py - 6, px + 4, py - 2); x.closePath(); x.fill(); outline(x, [[px - 4, py - 2], [px - 4.8, py - 6], [px - 4, py - 10], [px + 4, py - 10], [px + 4.8, py - 6], [px + 4, py - 2]], 0.6); x.fillStyle = '#b08a55'; x.beginPath(); x.ellipse(px, py - 10, 4, 1.6, 0, 0, 7); x.fill(); x.strokeStyle = 'rgba(36,21,8,.6)'; x.lineWidth = 0.6; x.stroke(); line(x, [px - 4.6, py - 4], [px + 4.6, py - 4], '#3a3a40', 1); line(x, [px - 4.8, py - 8], [px + 4.8, py - 8], '#3a3a40', 1); }
function crate(x, px, py, s) { const pts = [[px, py], [px + 6, py - 3], [px + 6, py - 9], [px, py - 6]]; face(x, pts, s.timber, {k: 0.1, seed: 40, amp: 0.1}); face(x, [[px, py], [px - 6, py - 3], [px - 6, py - 9], [px, py - 6]], s.timber, {k: -0.2, seed: 41, amp: 0.1}); face(x, [[px, py - 6], [px + 6, py - 9], [px, py - 12], [px - 6, py - 9]], s.timber, {k: 0.3, seed: 42, amp: 0.1}); line(x, [px + 1, py - 1.5], [px + 5, py - 7.5], 'rgba(36,21,8,.45)', 0.7); line(x, [px - 1, py - 1.5], [px - 5, py - 7.5], 'rgba(36,21,8,.45)', 0.7); }
function hay(x, px, py) { const g = x.createRadialGradient(px - 2, py - 6, 1, px, py - 4, 8); g.addColorStop(0, '#e8c46a'); g.addColorStop(1, '#8f6a22'); x.fillStyle = g; x.beginPath(); x.ellipse(px, py - 4, 7.5, 5, 0, 0, 7); x.fill(); const r = rng(9); for (let i = 0; i < 30; i++) { x.strokeStyle = i % 2 ? '#f1d98a' : '#7a5a1a'; x.lineWidth = 0.6; x.beginPath(); const ax = px + (r() - .5) * 13, ay = py - 4 + (r() - .5) * 8; x.moveTo(ax, ay); x.lineTo(ax + (r() - .5) * 5, ay + (r() - .5) * 3); x.stroke(); } x.strokeStyle = 'rgba(40,25,5,.6)'; x.lineWidth = 0.8; x.beginPath(); x.ellipse(px, py - 4, 7.5, 5, 0, 0, 7); x.stroke(); }
function logs(x, px, py) { for (let row = 0; row < 3; row++) for (let i = 0; i < 4 - row; i++) { const cx = px + i * 5 + row * 2.5, cy = py - 2 - row * 4; x.fillStyle = '#5a3d22'; x.fillRect(cx - 2.5, cy - 2.5, 14, 5); x.fillStyle = '#d9b67a'; x.beginPath(); x.ellipse(cx, cy, 2.5, 2.5, 0, 0, 7); x.fill(); x.strokeStyle = 'rgba(36,21,8,.6)'; x.lineWidth = 0.6; x.stroke(); x.strokeStyle = '#a67a48'; x.beginPath(); x.arc(cx, cy, 1.4, 0, 7); x.stroke(); } }
function jars(x, px, py, s) { for (let i = 0; i < 3; i++) { const cx = px + i * 6, cy = py - (i % 2) * 2; const g = x.createLinearGradient(cx - 3, 0, cx + 3, 0); g.addColorStop(0, '#7a4a28'); g.addColorStop(0.5, '#c88a52'); g.addColorStop(1, '#5a3418'); x.fillStyle = g; x.beginPath(); x.moveTo(cx - 1.5, cy - 8); x.quadraticCurveTo(cx - 4.5, cy - 5, cx - 2.5, cy); x.lineTo(cx + 2.5, cy); x.quadraticCurveTo(cx + 4.5, cy - 5, cx + 1.5, cy - 8); x.closePath(); x.fill(); x.strokeStyle = 'rgba(36,21,8,.6)'; x.lineWidth = 0.6; x.stroke(); x.fillStyle = '#2a1a0a'; x.beginPath(); x.ellipse(cx, cy - 8, 1.8, 0.8, 0, 0, 7); x.fill(); } }
function torch(x, px, py) { line(x, [px, py], [px, py - 9], '#3a2a1a', 1.6); dab(x, px, py - 10, 2, '#ff9a2a', 0.9); dab(x, px, py - 10.5, 1.2, '#ffe07a'); dab(x, px, py - 10, 5, '#ff9a2a', 0.18); }
function trough(x, px, py, s) { face(x, [[px, py], [px + 14, py - 7], [px + 14, py - 11], [px, py - 4]], s.timber, {k: 0, seed: 50, amp: 0.1}); face(x, [[px, py], [px - 4, py - 2], [px - 4, py - 6], [px, py - 4]], s.timber, {k: -0.25, seed: 51}); x.fillStyle = '#3a6a90'; path(x, [[px - 3, py - 5], [px, py - 3.5], [px + 13, py - 10], [px + 10.5, py - 11.5]]); x.fill(); }
