function openShed(x, bx, by, bw, bh, bht, s, o = {}) {
  const c = corners(bx, by, bw, bh);
  face(x, [c.top, c.right, c.bottom, c.left], o.floor || '#6e5a3c', {k: -0.1, seed: 17, amp: 0.22, dab: 3, noOutline: true});
  const wt = o.wallTex === undefined ? 'planks' : o.wallTex, wc = o.wall || s.timber;
  face(x, [c.left, c.top, up(c.top, bht), up(c.left, bht)], wc, {k: -0.42, tex: wt, ground: [c.left, c.top], ht: bht, seed: 18, amp: 0.1});
  face(x, [c.top, c.right, up(c.right, bht), up(c.top, bht)], wc, {k: -0.28, tex: wt, ground: [c.top, c.right], ht: bht, seed: 19, amp: 0.1});
  const g = x.createLinearGradient(0, c.top[1] - bht, 0, c.top[1] - bht + 14); g.addColorStop(0, 'rgba(0,0,0,.5)'); g.addColorStop(1, 'rgba(0,0,0,0)'); x.fillStyle = g; path(x, [up(c.left, bht), up(c.top, bht), up(c.right, bht), up(c.right, bht - 14), up(c.top, bht - 14), up(c.left, bht - 14)]); x.fill();
  return c;
}
function shedPosts(x, c, bht, col, n = 2) { const pts = [c.left, c.bottom, c.right]; for (let i = 0; i < 2; i++) for (let j = 0; j < n; j++) post(x, lerp(pts[i], pts[i + 1], j / n), bht, col); post(x, c.right, bht, col); }
function fence(x, p, q, s, h = 7, gap = 7) { const len = Math.hypot(q[0] - p[0], q[1] - p[1]); line(x, up(p, h * 0.7), up(q, h * 0.7), 'rgba(30,15,5,.8)', 2.2); line(x, up(p, h * 0.7), up(q, h * 0.7), shade(s.timber, 0.3), 1.2); line(x, up(p, h * 0.3), up(q, h * 0.3), 'rgba(30,15,5,.8)', 2); line(x, up(p, h * 0.3), up(q, h * 0.3), shade(s.timber, 0.3), 1.1); for (let d = 0; d <= len + 0.1; d += gap) { const u = Math.min(1, d / len); post(x, [p[0] + (q[0] - p[0]) * u, p[1] + (q[1] - p[1]) * u], h, s.timber, 2); } }
function palisade(x, p, q, s, h = 13) { const len = Math.hypot(q[0] - p[0], q[1] - p[1]); const r = rng(41); for (let d = 0; d <= len; d += 3.2) { const u = d / len; const ax = p[0] + (q[0] - p[0]) * u, ay = p[1] + (q[1] - p[1]) * u; const hh = h + (r() - 0.5) * 2; x.fillStyle = shade(s.timber, (Math.round(d / 3.2) % 2 ? 0.12 : -0.12)); x.fillRect(ax - 1.6, ay - hh, 3.2, hh); x.strokeStyle = 'rgba(30,15,5,.6)'; x.lineWidth = 0.5; x.strokeRect(ax - 1.6, ay - hh, 3.2, hh); x.fillStyle = shade(s.timber, 0.25); path(x, [[ax - 1.6, ay - hh], [ax, ay - hh - 2.5], [ax + 1.6, ay - hh]]); x.fill(); } line(x, up(p, h * 0.55), up(q, h * 0.55), 'rgba(30,15,5,.5)', 1.6); }
